function initPublicNavigation(){
 const menu=document.querySelector('#nav-menu'),toggle=document.querySelector('.nav-toggle'),header=document.querySelector('.site-header');
 if(!menu||!toggle||!header)return;
 if(!menu.querySelector('.nav-close'))menu.insertAdjacentHTML('afterbegin','<div class="mobile-menu-head"><strong>Menu Utama</strong><button type="button" class="nav-close" aria-label="Tutup menu">×</button></div>');
 let overlay=document.querySelector('.public-nav-overlay');
 if(!overlay){overlay=document.createElement('button');overlay.type='button';overlay.className='public-nav-overlay';overlay.setAttribute('aria-label','Tutup menu navigasi');header.insertAdjacentElement('afterend',overlay)}
 const isMobile=()=>matchMedia('(max-width: 767px)').matches;
 const closeSubmenus=except=>document.querySelectorAll('.nav-drop.submenu-open').forEach(d=>{if(d!==except){d.classList.remove('submenu-open');d.querySelector(':scope > button')?.setAttribute('aria-expanded','false')}});
 const closeMenu=()=>{document.body.classList.remove('mobile-menu-open');menu.classList.remove('open');toggle.setAttribute('aria-expanded','false');closeSubmenus()};
 const openMenu=()=>{document.body.classList.add('mobile-menu-open');menu.classList.add('open');toggle.setAttribute('aria-expanded','true')};
 toggle.addEventListener('click',e=>{e.preventDefault();document.body.classList.contains('mobile-menu-open')?closeMenu():openMenu()});
 menu.querySelector('.nav-close')?.addEventListener('click',closeMenu);overlay.addEventListener('click',closeMenu);
 document.querySelectorAll('.nav-drop>button').forEach(button=>button.addEventListener('click',e=>{
   e.preventDefault();const item=button.parentElement;
   if(isMobile()){const willOpen=!item.classList.contains('submenu-open');closeSubmenus(item);item.classList.toggle('submenu-open',willOpen);button.setAttribute('aria-expanded',String(willOpen));}
   else{const willOpen=!item.classList.contains('desktop-open');document.querySelectorAll('.nav-drop.desktop-open').forEach(d=>d.classList.remove('desktop-open'));item.classList.toggle('desktop-open',willOpen);button.setAttribute('aria-expanded',String(willOpen));}
 }));
 menu.querySelectorAll('a').forEach(link=>link.addEventListener('click',closeMenu));
 document.addEventListener('click',e=>{if(!isMobile()&&!e.target.closest('.nav-drop'))document.querySelectorAll('.nav-drop.desktop-open').forEach(d=>d.classList.remove('desktop-open'))});
 document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
 addEventListener('resize',()=>{if(!isMobile())closeMenu()},{passive:true});
}
